import { useState } from 'react';
import { 
  LayoutDashboard, 
  Map, 
  FileText, 
  Lightbulb,
  Rocket,
  Info,
  Compass
} from 'lucide-react';

const navItems = [
  { icon: LayoutDashboard, label: 'Dashboard' },
  { icon: FileText, label: 'Test Cases' },
  { icon: Map, label: 'Map Analysis' },
  { icon: Lightbulb, label: 'Insights' },
  { icon: Rocket, label: 'Future Scope' },
  { icon: Info, label: 'About' },
];

export function Sidebar() {
  const [active, setActive] = useState('Dashboard');

  return (
    <aside className="w-56 h-screen flex flex-col border-r border-white/5 bg-[#0a0e1a]/80 backdrop-blur-xl flex-shrink-0">
      <div className="flex-1 px-3 py-4">
        <nav className="space-y-1">
          {navItems.map((item) => {
            const isActive = active === item.label;
            return (
              <button
                key={item.label}
                onClick={() => setActive(item.label)}
                className={`w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm transition-all ${
                  isActive 
                    ? 'bg-cyan-500/10 text-cyan-400 border border-cyan-500/20' 
                    : 'text-gray-400 hover:text-white hover:bg-white/5'
                }`}
              >
                <item.icon className={`w-4 h-4 ${isActive ? 'text-cyan-400' : ''}`} />
                <span>{item.label}</span>
                {isActive && (
                  <span className="ml-auto w-0.5 h-5 bg-cyan-400 rounded-full shadow-[0_0_10px_rgba(0,200,255,0.3)]"></span>
                )}
              </button>
            );
          })}
        </nav>
      </div>

      <div className="p-4 border-t border-white/5">
        <div className="relative rounded-lg overflow-hidden bg-gradient-to-br from-cyan-500/5 to-emerald-500/5 border border-white/5 p-3">
          <div className="flex items-center gap-2">
            <Compass className="w-3 h-3 text-cyan-400" />
            <span className="text-[10px] text-gray-500">BHARAT</span>
          </div>
          <p className="text-[8px] text-gray-600 tracking-wider mt-0.5">BELOW AND BEYOND</p>
        </div>
      </div>
    </aside>
  );
}
